/* Minimal OOXML workbook writer. Cells are explicit strings/numbers, never formulas. */
(function(root){
const enc=new TextEncoder();
const xml=s=>String(s??'').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function col(n){let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s}
function crc(a){let c=0xffffffff;for(const b of a){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0}
function header(size,values){const a=new Uint8Array(size),v=new DataView(a.buffer);for(const [pos,n,len]of values)len===2?v.setUint16(pos,n,true):v.setUint32(pos,n,true);return a}
function zip(files){let offset=0,centralSize=0;const parts=[],central=[];for(const [name,text]of Object.entries(files)){const n=enc.encode(name),d=enc.encode(text),c=crc(d);const h=header(30,[[0,0x04034b50,4],[4,20,2],[14,c,4],[18,d.length,4],[22,d.length,4],[26,n.length,2]]);parts.push(h,n,d);const ch=header(46,[[0,0x02014b50,4],[4,20,2],[6,20,2],[16,c,4],[20,d.length,4],[24,d.length,4],[28,n.length,2],[42,offset,4]]);central.push(ch,n);centralSize+=46+n.length;offset+=30+n.length+d.length}return new Blob([...parts,...central,header(22,[[0,0x06054b50,4],[8,central.length/2,2],[10,central.length/2,2],[12,centralSize,4],[16,offset,4]])],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
// List validation is optional so ordinary report exports remain unchanged.
function listValidations(rules=[]){if(!rules.length)return '';return `<dataValidations count="${rules.length}">${rules.map(r=>{
 if(!/^[A-Z]{1,3}[1-9][0-9]*:[A-Z]{1,3}[1-9][0-9]*$/.test(r.range)||!Array.isArray(r.values)||!r.values.length||r.values.some(v=>typeof v!=='string'||/[",\r\n]/.test(v)))throw Error('Dropdown Excel tidak valid.');
 const list=r.values.join(',');if(list.length>253)throw Error('Pilihan dropdown terlalu panjang.');
 return `<dataValidation type="list" allowBlank="0" showDropDown="0" showInputMessage="1" showErrorMessage="1" errorStyle="stop" errorTitle="Jenis zakat tidak valid" error="Pilih jenis zakat dari dropdown." promptTitle="Jenis Zakat" prompt="Klik sel lalu pilih melalui panah dropdown." sqref="${xml(r.range)}"><formula1>${xml('"'+list+'"')}</formula1></dataValidation>`;
 }).join('')}</dataValidations>`}
function xlsx(sheets){const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main',rel='http://schemas.openxmlformats.org/package/2006/relationships',files={};files['[Content_Types].xml']=`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`;files['_rels/.rels']=`<Relationships xmlns="${rel}"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`;files['xl/workbook.xml']=`<workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((s,i)=>`<sheet name="${xml(s.name.slice(0,31))}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`;files['xl/_rels/workbook.xml.rels']=`<Relationships xmlns="${rel}">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}</Relationships>`;sheets.forEach((s,i)=>{files[`xl/worksheets/sheet${i+1}.xml`]=`<worksheet xmlns="${ns}"><sheetData>${s.rows.map((r,j)=>`<row r="${j+1}">${r.map((v,k)=>typeof v==='number'&&Number.isFinite(v)?`<c r="${col(k)}${j+1}"><v>${v}</v></c>`:`<c r="${col(k)}${j+1}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')}</row>`).join('')}</sheetData>${listValidations(s.validations)}</worksheet>`});return zip(files)}
root.SimasExport={xlsx};if(typeof module!=='undefined')module.exports={xlsx};
})(typeof globalThis!=='undefined'?globalThis:this);
